window.docContents[139].resolve({"/The-Proved-Spine/Foundations-___-system-and-object-_LPAR_Dybk___r-Ch___-3_RPAR_/#PropertyKindCalculus-Blueprint--The-Proved-Spine--Foundations-___-system-and-object-_LPAR_Dybk___r-Ch___-3_RPAR_":{"contents":"\n\nA system (Dybkær §3.3) is a demarcated arrangement of elements and their\nrelationships; object (§3.3 Note 6) is given as a synonym. Specified abstractly\nby identity here; the mereological structure that extensivity needs is added in a\nlater module.\n\nA one-field structure with DecidableEq; nothing to prove. The synonym\nObject := System keeps the instance layer reading as \"characterizes an\nobject\".\n\n","context":"PropertyKindCalculus Blueprint\u0009The Proved Spine","header":"4.1. Foundations — system and object (Dybkær Ch. 3)","id":"/The-Proved-Spine/Foundations-___-system-and-object-_LPAR_Dybk___r-Ch___-3_RPAR_/#PropertyKindCalculus-Blueprint--The-Proved-Spine--Foundations-___-system-and-object-_LPAR_Dybk___r-Ch___-3_RPAR_"}});